func main() {
	a := &App{}
	gk.RunHeadless("frame\nframe\n", func(cx *gk.Cx) {
		sampleAct = gk.NewAction(cx, "gensample.sample")
		a.root = gk.NewView(nil, a.rootView)
		gk.OpenWindow(cx, "gensample", 640, 480, a.root)
	})
	fmt.Printf("gensample: done runs=%d\n", a.runs)
}
